@isTest private class CurrentBaseMetadataDtoDeterministic005Test {
    @isTest static void metadataDtoDeterministic005Witness() {
        Metadata.SidebarComponent sidebar = new Metadata.SidebarComponent();
        System.assertNotEquals(null, sidebar);
        sidebar.label = 'Help';
        sidebar.lookup = 'Lookup';
        sidebar.page_x = 'Page';
        sidebar.relatedLists = new List<Metadata.RelatedList>{new Metadata.RelatedList()};
        sidebar.unit = 'px';
        sidebar.updateAction = 'Update';
        sidebar.width = 200;
        System.assertEquals('Help', sidebar.label);
        System.assertEquals('Lookup', sidebar.lookup);
        System.assertEquals('Page', sidebar.page_x);
        System.assertEquals(1, sidebar.relatedLists.size());
        System.assertEquals('px', sidebar.unit);
        System.assertEquals('Update', sidebar.updateAction);
        System.assertEquals(200, sidebar.width);

        Metadata.SortOrder ascOrder = Metadata.SortOrder.Asc_x;
        Metadata.SortOrder descOrder = Metadata.SortOrder.Desc_x;
        System.assertEquals(true, ascOrder.equals(ascOrder));
        System.assertNotEquals(null, ascOrder.hashCode());
        System.assertEquals(0, ascOrder.ordinal());
        System.assertEquals(true, Metadata.SortOrder.valueOf('Asc_x').equals(ascOrder));
        System.assertEquals(2, Metadata.SortOrder.values().size());
        System.assertEquals(true, Metadata.SortOrder.Desc_x.equals(descOrder));

        Metadata.StatusCode statusCode = Metadata.StatusCode.APEX_FAILED;
        System.assertEquals(true, statusCode.equals(statusCode));
        System.assertNotEquals(null, statusCode.hashCode());
        System.assertEquals(true, Metadata.StatusCode.valueOf('APEX_FAILED').equals(statusCode));
        System.assert(Metadata.StatusCode.values().size() > 0);

        Metadata.SubtabComponents subtab = new Metadata.SubtabComponents();
        System.assertNotEquals(null, subtab);
        subtab.component = new List<Metadata.ConsoleComponent>{new Metadata.ConsoleComponent()};
        subtab.containers = new List<Metadata.Container>{new Metadata.Container()};
        System.assertEquals(1, subtab.component.size());
        System.assertEquals(1, subtab.containers.size());

        Metadata.SummaryLayout summary = new Metadata.SummaryLayout();
        System.assertNotEquals(null, summary);
        summary.masterLabel = 'Summary';
        summary.sizeX = 1;
        summary.sizeY = 2;
        summary.sizeZ = 3;
        summary.summaryLayoutItems = new List<Metadata.SummaryLayoutItem>{new Metadata.SummaryLayoutItem()};
        summary.summaryLayoutStyle = Metadata.SummaryLayoutStyleEnum.Default_x;
        System.assertEquals('Summary', summary.masterLabel);
        System.assertEquals(1, summary.sizeX);
        System.assertEquals(2, summary.sizeY);
        System.assertEquals(3, summary.sizeZ);
        System.assertEquals(1, summary.summaryLayoutItems.size());
        System.assertEquals(true, Metadata.SummaryLayoutStyleEnum.Default_x.equals(summary.summaryLayoutStyle));

        Metadata.SummaryLayoutItem item = new Metadata.SummaryLayoutItem();
        System.assertNotEquals(null, item);
        item.customLink = 'Link';
        item.field = 'Name';
        item.posX = 1;
        item.posY = 2;
        item.posZ = 3;
        System.assertEquals('Link', item.customLink);
        System.assertEquals('Name', item.field);
        System.assertEquals(1, item.posX);
        System.assertEquals(2, item.posY);
        System.assertEquals(3, item.posZ);

        Metadata.SummaryLayoutStyleEnum style = Metadata.SummaryLayoutStyleEnum.Default_x;
        System.assertEquals(true, style.equals(style));
        System.assertNotEquals(null, style.hashCode());
        System.assertEquals(2, style.ordinal());
        System.assertEquals(true, Metadata.SummaryLayoutStyleEnum.valueOf('Default_x').equals(style));
        System.assertEquals(10, Metadata.SummaryLayoutStyleEnum.values().size());

        Metadata.UiBehavior behavior = Metadata.UiBehavior.Required;
        System.assertEquals(true, behavior.equals(behavior));
        System.assertNotEquals(null, behavior.hashCode());
        System.assertEquals(2, behavior.ordinal());
        System.assertEquals(true, Metadata.UiBehavior.valueOf('Required').equals(behavior));
        System.assertEquals(3, Metadata.UiBehavior.values().size());

        System.assertNotEquals(null, sidebar.clone());
        System.assertNotEquals(null, subtab.clone());
        System.assertNotEquals(null, summary.clone());
        System.assertNotEquals(null, item.clone());
    }
}
